package cn.zhuatech.grc.controller; import cn.zhuatech.grc.common.ApiResponse; import cn.zhuatech.grc.dto.GrcDto.*; import cn.zhuatech.grc.service.GrcService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('COMPLIANCE_ANALYST','ADMIN')") public class ComplianceController {private final GrcService service;public ComplianceController(GrcService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
